<?php declare(strict_types=1); ?>
<div class="mb-5 flex justify-end"><a class="btn btn-primary" href="<?= e(admin_url($kind.'/new')) ?>">Add <?= e(strtolower($config['label'])) ?></a></div><div class="card divide-y divide-hairline"><?php if(!$rows): ?><p class="p-8 text-center text-muted">No records yet.</p><?php endif; ?><?php foreach($rows as $item): ?><a class="flex items-center gap-4 px-5 py-4 hover:bg-canvas" href="<?= e(admin_url($kind.'/'.$item['id'])) ?>"><div class="flex-1"><p class="font-semibold text-navy-700"><?= e($item['title']) ?></p><p class="t-meta text-muted"><?= e($kind==='careers'?$item['location']:($item['note']?:$item['slug'])) ?></p></div><?php if($kind==='careers'): ?><span class="badge <?= $item['closed_at']?'bg-signal-600/10 text-signal-600':($item['published_at']?'bg-verified/10 text-verified':'bg-navy-100 text-navy-700') ?>"><?= $item['closed_at']?'Closed':($item['published_at']?'Published':'Draft') ?></span><?php elseif($item['featured']): ?><span class="badge bg-gold-100 text-gold-600">Featured</span><?php endif; ?><?= icon('chevron-right','h-4 w-4 text-muted') ?></a><?php endforeach; ?></div>
